properties.query:
// LastPass master password changes in the last 2 hours
let LastPassResets =
  prod_LastPass_AuditLogs_CL
  | where TimeGenerated >= ago(2h)
  | where Action_s == "Master password changed"
  | project LPTime = TimeGenerated,
            UserPrincipalName = Username_s,
            LPIP = Ip_s;
// Successful Entra ID sign-ins in the last 2 hours (ResultType == 0)
let SuccessSignins =
  SigninLogs
  | where TimeGenerated >= ago(2h)
  | where ResultType == 0
  | project UserPrincipalName, LPIP = IPAddress, SigninTime = TimeGenerated;
// Return LastPass resets with NO matching successful sign-in from the same IP
LastPassResets
| join kind=leftanti (SuccessSignins) on UserPrincipalName, LPIP
| project
    TimeGenerated = LPTime,
    UserPrincipalName,
    LastPassLogIPAddress = LPIP

alertDetailsOverride.alertDescriptionFormat:
{{UserPrincipalName}} reset their LastPass master password but there were no successful sign-ins
from the same IP within the rule window.

IP Address: {{LastPassLogIPAddress}}

properties.query:
let dt_lookBack = 1h;
let ioc_lookBack = 14d;
ThreatIntelligenceIndicator
| where TimeGenerated >= ago(ioc_lookBack) and ExpirationDateTime > now()
| where Active == true
// Picking up only IOC's that contain the entities we want
| where isnotempty(NetworkIP) or isnotempty(EmailSourceIpAddress) or isnotempty(NetworkDestinationIP) or isnotempty(NetworkSourceIP)
// As there is potentially more than 1 indicator type for matching IP, taking Network IP first, then others if that is empty.
// Taking the first non-empty value based on potential IOC match availability
| extend TI_ipEntity = iff(isnotempty(NetworkIP), NetworkIP, NetworkDestinationIP)
| extend TI_ipEntity = iff(isempty(TI_ipEntity) and isnotempty(NetworkSourceIP), NetworkSourceIP, TI_ipEntity)
| extend TI_ipEntity = iff(isempty(TI_ipEntity) and isnotempty(EmailSourceIpAddress), EmailSourceIpAddress, TI_ipEntity)
| join (
    LastPassNativePoller_CL | where todatetime(Time_s) >= ago(dt_lookBack)
    | where Action_s != "Reporting"
    // renaming time column so it is clear the log this came from
    | extend LastPass_TimeGenerated = todatetime(Time_s)
)
on $left.TI_ipEntity == $right.IP_Address_s
| summarize LatestIndicatorTime = arg_max(TimeGenerated, *) by IndicatorId
| project LatestIndicatorTime, Description, ActivityGroupNames, IndicatorId, ThreatType, Url, ExpirationDateTime, ConfidenceScore, LastPass_TimeGenerated, 
TI_ipEntity, IP_Address_s, Username_s, Action_s, Data_s, NetworkIP, NetworkDestinationIP, NetworkSourceIP, EmailSourceIpAddress
| extend timestamp = LastPass_TimeGenerated, AccountCustomEntity = Username_s, IPCustomEntity = IP_Address_s, URLCustomEntity = Url

