let getWeekdayName = (dt:datetime) {
  case(
      dayofweek(dt) == 1d, "Monday",
      dayofweek(dt) == 2d, "Tuesday",
      dayofweek(dt) == 3d, "Wednesday",
      dayofweek(dt) == 4d, "Thursday",
      dayofweek(dt) == 5d, "Friday",
      dayofweek(dt) == 6d, "Saturday",
      "Sunday"
  )
};
let Rota = datatable(
    DayOfWeek:string,
    OnDuty:string,
    Standby:string,
